// Helpers over the `projects` content collection (generated by scripts/fetch-content.mjs).
import { getCollection, type CollectionEntry } from 'astro:content';
import { services, type Service } from './site';

export type Project = CollectionEntry<'projects'>['data'];
export type ProjectPhoto = Project['photos'][number];

/** Newest first. */
export async function getProjects(): Promise<Project[]> {
  const entries = await getCollection('projects');
  return entries.map((e) => e.data).sort((a, b) => b.publishedAt.getTime() - a.publishedAt.getTime());
}

/** Featured first, then newest. */
export function pickRecent(projects: Project[], n: number): Project[] {
  return [...projects.filter((p) => p.featured), ...projects.filter((p) => !p.featured)].slice(0, n);
}

export function serviceOf(p: Project): Service | undefined {
  return services.find((s) => s.slug === p.serviceSlug);
}

export function projectPath(p: Pick<Project, 'slug'>): string {
  return `/projects/${p.slug}/`;
}

export function coverOf(p: Project): ProjectPhoto {
  return p.photos.find((ph) => ph.id === p.cover) ?? p.photos[0];
}

/** Up to `n` related projects: same service first, then same town, then newest. */
export function relatedTo(p: Project, all: Project[], n = 3): Project[] {
  const others = all.filter((o) => o.slug !== p.slug);
  const rank = (o: Project) => (o.serviceSlug === p.serviceSlug ? 0 : o.townSlug === p.townSlug ? 1 : 2);
  return others
    .map((o, i) => ({ o, i, r: rank(o) }))
    .sort((a, b) => a.r - b.r || a.i - b.i)
    .slice(0, n)
    .map((x) => x.o);
}

export function monthYear(iso: string): string {
  return new Date(`${iso}T12:00:00Z`).toLocaleDateString('en-US', { month: 'long', year: 'numeric', timeZone: 'UTC' });
}

/** Before/after pairs by sortOrder, plus every photo that is not part of a pair. */
export function splitPhotos(p: Project) {
  const byOrder = (a: ProjectPhoto, b: ProjectPhoto) => a.sortOrder - b.sortOrder;
  const before = p.photos.filter((x) => x.role === 'before').sort(byOrder);
  const after = p.photos.filter((x) => x.role === 'after').sort(byOrder);
  const pairs: { before: ProjectPhoto; after: ProjectPhoto }[] = [];
  const paired = new Set<string>();
  for (const b of before) {
    const a = after.find((x) => x.sortOrder === b.sortOrder && !paired.has(x.id));
    if (a) {
      pairs.push({ before: b, after: a });
      paired.add(b.id);
      paired.add(a.id);
    }
  }
  const rest = p.photos.filter((x) => !paired.has(x.id)).sort(byOrder);
  return { pairs, rest };
}
